    { const char * tb_v3680 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
