    { const char * tb_v3683 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
