    { const char * tb_v5400 = "        sel_getUid(\"texture2DDescriptorWithPixelFormat:width:height:mipmapped:\"), 252, (unsigned long)tb_gw, (unsigned long)tb_gh, NO);\n"; *(const char * *)tb_grow(v_lines) = tb_v5400; }
