    { const char * tb_v6135 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6135; }
    { const char * tb_v6136 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6136; }
    { const char * tb_v6137 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6137; }
