    { const char * tb_v6162 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6162; }
    { const char * tb_v6163 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6163; }
    { const char * tb_v6164 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6164; }
    { const char * tb_v6165 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6165; }
    { const char * tb_v6166 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v6166; }
    { const char * tb_v6167 = "    double ax[16], ay[16], bx[16], by[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v6167; }
    { const char * tb_v6168 = "    for (int i = 0; i < n; i++) { ax[i] = px[i]; ay[i] = py[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6168; }
    { const char * tb_v6169 = "    for (int side = 0; side < 4 && n > 0; side++) {   // Сазерленд — Ходжман: по одной стороне рамки\n"; *(const char * *)tb_grow(v_lines) = tb_v6169; }
    { const char * tb_v6170 = "        int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6170; }
