    { const char * tb_v6208 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6208; }
    { const char * tb_v6209 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v6209; }
    { const char * tb_v6210 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6210; }
    { const char * tb_v6211 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6211; }
    { const char * tb_v6212 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6212; }
    { const char * tb_v6213 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6213; }
    { const char * tb_v6214 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6214; }
    { const char * tb_v6215 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6215; }
    { const char * tb_v6216 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v6216; }
    { const char * tb_v6217 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6217; }
    { const char * tb_v6218 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6218; }
    { const char * tb_v6219 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6219; }
    { const char * tb_v6220 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v6220; }
    { const char * tb_v6221 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v6221; }
    { const char * tb_v6222 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6222; }
    { const char * tb_v6223 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6223; }
    { const char * tb_v6224 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v6224; }
    { const char * tb_v6225 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6225; }
    { const char * tb_v6226 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v6226; }
    { const char * tb_v6227 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v6227; }
    { const char * tb_v6228 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6228; }
    { const char * tb_v6229 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v6229; }
    { const char * tb_v6230 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v6230; }
    { const char * tb_v6231 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v6231; }
    { const char * tb_v6232 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6232; }
    { const char * tb_v6233 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6233; }
    { const char * tb_v6234 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6234; }
    { const char * tb_v6235 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v6235; }
    { const char * tb_v6236 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v6236; }
    { const char * tb_v6237 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v6237; }
    { const char * tb_v6238 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6238; }
    { const char * tb_v6239 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v6239; }
    { const char * tb_v6240 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v6240; }
    { const char * tb_v6241 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6241; }
    { const char * tb_v6242 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v6242; }
    { const char * tb_v6243 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6243; }
    { const char * tb_v6244 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6244; }
    { const char * tb_v6245 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6245; }
    { const char * tb_v6246 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6246; }
    { const char * tb_v6247 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6247; }
    { const char * tb_v6248 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6248; }
    { const char * tb_v6249 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6249; }
    { const char * tb_v6250 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v6250; }
    { const char * tb_v6251 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v6251; }
    { const char * tb_v6252 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v6252; }
    { const char * tb_v6253 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v6253; }
    { const char * tb_v6254 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v6254; }
    { const char * tb_v6255 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v6255; }
    { const char * tb_v6256 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v6256; }
    { const char * tb_v6257 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v6257; }
    { const char * tb_v6258 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v6258; }
    { const char * tb_v6259 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v6259; }
    { const char * tb_v6260 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v6260; }
    { const char * tb_v6261 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v6261; }
    { const char * tb_v6262 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v6262; }
    { const char * tb_v6263 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v6263; }
    { const char * tb_v6264 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v6264; }
    { const char * tb_v6265 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6265; }
    { const char * tb_v6266 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6266; }
    { const char * tb_v6267 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v6267; }
    { const char * tb_v6268 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v6268; }
    { const char * tb_v6269 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6269; }
    { const char * tb_v6270 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6270; }
    { const char * tb_v6271 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v6271; }
    { const char * tb_v6272 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v6272; }
    { const char * tb_v6273 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6273; }
    { const char * tb_v6274 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v6274; }
    { const char * tb_v6275 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6275; }
    { const char * tb_v6276 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6276; }
    { const char * tb_v6277 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6277; }
    { const char * tb_v6278 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6278; }
