    { const char * tb_v6282 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6282; }
    { const char * tb_v6283 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6283; }
    { const char * tb_v6284 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v6284; }
    { const char * tb_v6285 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6285; }
