    { const char * tb_v6293 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6293; }
    { const char * tb_v6294 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6294; }
    { const char * tb_v6295 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6295; }
