    { const char * tb_v6298 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6298; }
    { const char * tb_v6299 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6299; }
