    { const char * tb_v6301 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6301; }
    { const char * tb_v6302 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6302; }
    { const char * tb_v6303 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6303; }
    { const char * tb_v6304 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v6304; }
    { const char * tb_v6305 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v6305; }
