    { const char * tb_v6307 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6307; }
    { const char * tb_v6308 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v6308; }
    { const char * tb_v6309 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6309; }
    { const char * tb_v6310 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6310; }
    { const char * tb_v6311 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6311; }
    { const char * tb_v6312 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v6312; }
    { const char * tb_v6313 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v6313; }
    { const char * tb_v6314 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6314; }
