    { const char * tb_v6318 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6318; }
    { const char * tb_v6319 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v6319; }
    { const char * tb_v6320 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6320; }
    { const char * tb_v6321 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6321; }
    { const char * tb_v6322 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6322; }
    { const char * tb_v6323 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v6323; }
    { const char * tb_v6324 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6324; }
    { const char * tb_v6325 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6325; }
    { const char * tb_v6326 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6326; }
