    { const char * tb_v6339 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6339; }
    { const char * tb_v6340 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6340; }
