    { const char * tb_v6518 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v6518; }
    { const char * tb_v6519 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v6519; }
    { const char * tb_v6520 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6520; }
    { const char * tb_v6521 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6521; }
    { const char * tb_v6522 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6522; }
    { const char * tb_v6523 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6523; }
    { const char * tb_v6524 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v6524; }
    { const char * tb_v6525 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6525; }
    { const char * tb_v6526 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6526; }
    { const char * tb_v6527 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v6527; }
    { const char * tb_v6528 = "    pc->size[0] = (float)tb_gw; pc->size[1] = (float)tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v6528; }
    { const char * tb_v6529 = "    pc->tbase = (int32_t)(m->gt + g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v6529; }
    { const char * tb_v6530 = "    pc->f = (int32_t)tb_m3_f(); pc->gw = tb_gw; pc->gh = tb_gh; pc->cull = g->y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6530; }
    { const char * tb_v6531 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6531; }
    { const char * tb_v6532 = "TB_API long long *tb_3i = 0;   // углы сетки после камеры в целых: x, y, D\n"; *(const char * *)tb_grow(v_lines) = tb_v6532; }
    { const char * tb_v6533 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6533; }
    { const char * tb_v6534 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v6534; }
    { const char * tb_v6535 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v6535; }
    { const char * tb_v6536 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6536; }
    { const char * tb_v6537 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6537; }
    { const char * tb_v6538 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v6538; }
    { const char * tb_v6539 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6539; }
    { const char * tb_v6540 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v6540; }
    { const char * tb_v6541 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6541; }
    { const char * tb_v6542 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6542; }
    { const char * tb_v6543 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v6543; }
    { const char * tb_v6544 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v6544; }
    { const char * tb_v6545 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v6545; }
    { const char * tb_v6546 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v6546; }
    { const char * tb_v6547 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v6547; }
    { const char * tb_v6548 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6548; }
    { const char * tb_v6549 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v6549; }
    { const char * tb_v6550 = "typedef struct { tb_mesh *m; long long id; int cull; long long ri, rbatch; tb_grec rec; } tb_m3_go;\n"; *(const char * *)tb_grow(v_lines) = tb_v6550; }
    { const char * tb_v6551 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v6551; }
    { const char * tb_v6552 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6552; }
    { const char * tb_v6553 = "    tb_mesh *m = go->m;\n"; *(const char * *)tb_grow(v_lines) = tb_v6553; }
    { const char * tb_v6554 = "    if (tb_gpu_on && tb_gpu_mesh) {   // видеокарта считает сама: только запись и «нарисуй треугольники t0.. из сетки»\n"; *(const char * *)tb_grow(v_lines) = tb_v6554; }
    { const char * tb_v6555 = "        if (tb_gin == TB_GI_CAP || (go->rbatch != tb_gbatch && tb_grn == TB_GR_CAP)) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6555; }
    { const char * tb_v6556 = "        if (go->rbatch != tb_gbatch) {   // запись этого вызова ещё не в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v6556; }
    { const char * tb_v6557 = "            go->ri = tb_grn++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6557; }
