    { const char * tb_v6562 = "        if (g && g->m == 3u && g->x0 == (int32_t)go->id && g->y0 == go->cull && g->ox == t0 && g->oy == tn &&\n"; *(const char * *)tb_grow(v_lines) = tb_v6562; }
    { const char * tb_v6563 = "            g->x1 + g->y1 == go->ri && (long long)(g->y1 + 1) * tn < 2000000000) g->y1++;   // та же сетка подряд: одним вызовом\n"; *(const char * *)tb_grow(v_lines) = tb_v6563; }
    { const char * tb_v6564 = "        else tb_gpu_add(go->id, go->cull, go->ri, 1, t0, tn, 0, 3u);\n"; *(const char * *)tb_grow(v_lines) = tb_v6564; }
    { const char * tb_v6565 = "        m->gused = tb_gbatch;\n"; *(const char * *)tb_grow(v_lines) = tb_v6565; }
