    { const char * tb_v6567 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6567; }
    { const char * tb_v6568 = "    // процессор: та же целая формула (кадр для сверки, или видеокарта без своего 3D, или без видеокарты)\n"; *(const char * *)tb_grow(v_lines) = tb_v6568; }
