    { const char * tb_v6572 = "        tb_3i = (long long *)realloc(tb_3i, sizeof(long long) * tb_3icap);\n"; *(const char * *)tb_grow(v_lines) = tb_v6572; }
    { const char * tb_v6573 = "        tb_3ist = (long long *)realloc(tb_3ist, sizeof(long long) * tb_3icap / 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v6573; }
    { const char * tb_v6574 = "        memset(tb_3ist, 0, sizeof(long long) * (tb_3icap / 3));\n"; *(const char * *)tb_grow(v_lines) = tb_v6574; }
    { const char * tb_v6575 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6575; }
    { const char * tb_v6576 = "    long long fq = tb_m3_f(), gen = ++tb_3igen;\n"; *(const char * *)tb_grow(v_lines) = tb_v6576; }
    { const char * tb_v6577 = "    for (long long t = t0; t < t0 + tn; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6577; }
    { const char * tb_v6578 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v6578; }
    { const char * tb_v6579 = "        for (int i = 0; i < 3; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6579; }
    { const char * tb_v6580 = "            if (tb_3ist[ti[i]] != gen) { tb_3ist[ti[i]] = gen; tb_m3_corner(go->rec.r, m->vi + 4 * ti[i], fq, tb_3i + 3 * ti[i]); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6580; }
    { const char * tb_v6581 = "        long long q[6];\n"; *(const char * *)tb_grow(v_lines) = tb_v6581; }
    { const char * tb_v6582 = "        uint32_t pl[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6582; }
