    { const char * tb_v6586 = "// куски сетки: треугольники делятся пополам по самой длинной стороне, пока в куске не больше 256.\n"; *(const char * *)tb_grow(v_lines) = tb_v6586; }
    { const char * tb_v6587 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v6587; }
    { const char * tb_v6588 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v6588; }
    { const char * tb_v6589 = "static const float *tb_kd_c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6589; }
